2	//
3	// Renders every route and fails on an uncaught runtime error. This is the plane
4	// the capstone showed was missing, and it is aimed at a family rather than a
5	// rule: three of the four genuinely fatal defects that run produced were
6	// dependency-injection failures, and no AST rule reached any of them.
7	//
8	//   - `NgIconsModule` imported with no root-level `provideIcons`: throws at
9	//     bootstrap, blank page, three of six builds.
10	//   - A component-scoped ViewModel injected but never provided: NullInjectorError
11	//     on first render.
12	//   - `hlm-dialog-content` rendered inline instead of on `*hlmDialogPortal`:
13	//     spartan supplies `BrnDialogRef` through the portal, so inline content has
14	//     no provider and the screen throws NG0201 when the dialog is constructed.
15	//
16	// Every one of those compiles cleanly, passes strictTemplates, and passes every
17	// gate in this repo. They are well-formed code with real primitives and checked
18	// types that fails only when Angular actually assembles the graph. A static rule
19	// cannot see it; a browser sees it immediately.
20	//
21	// The cost of adding this was near zero, which is the uncomfortable part: the
22	// harness ALREADY boots every build for the responsive audit and was throwing
23	// the console away.
24	//
25	// This gate is deliberately NOT double-encoded the way the AST rules are. A
26	// thrown error is an observation the browser hands you, not a judgment about the
27	// code, so a second independent implementation would be the same three lines of
28	// Playwright API. The independence that matters is kept elsewhere: the responsive
29	// auditor captures page errors during its OWN navigation, in its own code path,
30	// and the driver records both. See responsive-spec.md.
31	//
32	// Usage:
33	//   node harness/gate/check-boot.mjs [--route dashboard --route roster ...]
34	
35	import { execFileSync } from 'node:child_process';
36	import { dirname, join } from 'node:path';
37	import { fileURLToPath } from 'node:url';
38	import { serveStatic, launchChromium } from '../playwright/serve-and-visit.mjs';
39	
40	const here = dirname(fileURLToPath(import.meta.url));
41	const ROOT = join(here, '..', '..');
42	const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
43	
44	// Noise that is not an application fault. Kept deliberately short: a gate that
45	// filters aggressively stops being a gate. Anything not listed here fails.
46	const IGNORE = [
47	  /favicon\.ico/i,
48	  /Failed to load resource.*404.*favicon/i,
49	];
50	
51	const isNoise = (text) => IGNORE.some((re) => re.test(text));
52	
53	/**
54	 * Visit one route and collect anything the page threw or logged as an error.
55	 * Uncaught exceptions arrive on `pageerror`; Angular's own logged errors (which
56	 * do not always throw past the framework) arrive as console messages of type
57	 * `error`, and NG0201 in particular surfaces that way under some zone configs,
58	 * so both are collected.
59	 */
60	export async function bootErrorsForRoute(browser, origin, route, { viewport = 1280, interact = true, maxClicks = 14 } = {}) {
61	  const context = await browser.newContext({ viewport: { width: viewport, height: 900 }, deviceScaleFactor: 1 });
62	  const page = await context.newPage();
63	  const errors = [];
64	  page.on('pageerror', (err) => errors.push({ kind: 'pageerror', text: String(err && err.message ? err.message : err) }));
65	  page.on('console', (msg) => {
66	    if (msg.type() === 'error') errors.push({ kind: 'console.error', text: msg.text() });
67	  });
68	  const url = `${origin}/${route}`;
69	  try {
70	    await page.goto(url, { waitUntil: 'networkidle' });
71	    // Angular bootstraps and renders asynchronously; a DI failure in a routed
72	    // component surfaces after navigation settles, not during it.
73	    await page.waitForTimeout(400);
74	
75	    // A LOAD-time sweep alone is not enough, and the capstone proved it. The
76	    // NG0201 dialog fault hides behind `@if (vm.showRetireDialog())`: the
77	    // content is never instantiated until someone clicks Retire, so navigation
78	    // sees nothing and the screen looks perfect. Two of the three known DI
79	    // faults are load-time; the third is one click away.
80	    //
81	    // So click. Every visible, enabled button on the route, in order, bounded.
82	    // This is deliberately blunt rather than clever: it needs no knowledge of
83	    // the app, and an unknown app is exactly the situation a gate is for.
84	    // Playwright auto-dismisses native dialogs when no handler is attached, so
85	    // a stray window.confirm cannot wedge it.
86	    if (interact) {
87	      const buttons = page.locator('button:visible:not([disabled])');
88	      const n = Math.min(await buttons.count(), maxClicks);
89	      for (let i = 0; i < n; i++) {
90	        try {
91	          await buttons.nth(i).click({ timeout: 1500, noWaitAfter: true });
92	          await page.waitForTimeout(150);
93	          // A click may navigate away; go back so the remaining controls on the
94	          // route under test still get exercised.
95	          if (!page.url().endsWith(`/${route}`)) {
96	            await page.goto(url, { waitUntil: 'networkidle' });
97	            await page.waitForTimeout(200);
98	          }
99	        } catch {
100	          // A control that will not accept a click is not a runtime fault.
101	          // Detached nodes, overlays and timeouts are all normal here; only what
102	          // the PAGE throws counts, and that arrives on the listeners above.
103	        }
104	      }
105	    }
106	  } catch (e) {
107	    errors.push({ kind: 'navigation', text: String(e && e.message ? e.message : e) });
108	  } finally {
109	    await context.close();
110	  }
111	  return errors.filter((e) => !isNoise(e.text)).map((e) => ({ ...e, route }));
112	}
