114	export async function assertBoots({ origin, routes, browser: given, viewport = 1280 }) {
115	  const browser = given ?? (await launchChromium());
116	  const failures = [];
117	  try {
118	    for (const route of routes) {
119	      failures.push(...(await bootErrorsForRoute(browser, origin, route, { viewport })));
120	    }
121	  } finally {
122	    if (!given) await browser.close();
123	  }
124	  return { failures };
125	}
