129	  for (const f of failures) (byRoute[f.route] ??= []).push(f);
130	  const lines = [];
131	  lines.push(`Boot gate failed: ${failures.length} runtime error(s) across ${Object.keys(byRoute).length} route(s).`);
132	  lines.push('');
133	  for (const [route, fs_] of Object.entries(byRoute)) {
134	    lines.push(`  /${route}`);
135	    for (const f of fs_.slice(0, 5)) lines.push(`    [${f.kind}] ${f.text.split('\n')[0].slice(0, 200)}`);
136	    if (fs_.length > 5) lines.push(`    ... and ${fs_.length - 5} more`);
137	  }
138	  lines.push('');
139	  lines.push('The application compiles but throws when the browser renders it. These are almost always');
140	  lines.push('dependency-injection faults, which no compiler and no lint rule can see. The three this');
141	  lines.push('harness has measured, and what each one actually means:');
142	  lines.push('');
143	  lines.push('  "No icons have been provided"    -> NgIconsModule is an NgModule and resolves in the');
144	  lines.push('                                      ENVIRONMENT injector, so a component-level');
145	  lines.push('                                      provideIcons does not satisfy it. Import NgIcon');
146	  lines.push('                                      instead (see the house-style skill), or register at');
147	  lines.push('                                      application level in app.config.ts.');
148	  lines.push('  "No provider for BrnDialogRef"   -> hlm-dialog-content must sit on an *hlmDialogPortal');
149	  lines.push('                                      template; spartan supplies the dialog ref through');
150	  lines.push('                                      that portal. Rendering the content inline gives it');
151	  lines.push('                                      no provider. The spartan composition doc shows the');
152	  lines.push('                                      canonical shape; ask the spartan MCP if unsure.');
153	  lines.push('  "NullInjectorError: ...ViewModel" -> a component-scoped ViewModel was injected but not');
154	  lines.push('                                      listed in that component\'s own providers array.');
155	  lines.push('');
156	  lines.push('Fix the cause, then run `npm run check:boot` again. Do not work around it by removing the');
157	  lines.push('feature: a screen that does not render is not a screen that passes.');
158	  return lines.join('\n');
159	}
