1	import { execFileSync } from 'node:child_process';
2	import { dirname, join } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { serveStatic, launchChromium, visitBreakpoint } from '../playwright/serve-and-visit.mjs';
5	import { formatCorrectiveMessage } from './responsive-guidance.mjs';
6	
7	const here = dirname(fileURLToPath(import.meta.url));
8	const ROOT = join(here, '..', '..');
9	const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
10	
11	// Independent in-page check. Distinct code from the auditor's inPageMeasure.
12	function pageCheck({ tol, anchorSelector }) {
13	  const vw = window.innerWidth;
14	  const fails = [];
15	  const sel = (el) => {
16	    if (el.id) return el.tagName.toLowerCase() + '#' + el.id;
17	    const c = (el.getAttribute && el.getAttribute('class') || '').trim().split(/\s+/).filter(Boolean)[0];
18	    return el.tagName.toLowerCase() + (c ? '.' + c : '');
19	  };
20	  const scrollAncestor = (el, root) => {
21	    let e = el.parentElement;
22	    while (e && e !== root.parentElement) {
23	      const o = getComputedStyle(e).overflowX;
24	      if (o === 'auto' || o === 'scroll') return true;
25	      e = e.parentElement;
26	    }
27	    return false;
28	  };
29	  // Hidden-element exemption, expressed differently from the auditor's: use
30	  // Element.closest() (native ancestor-selector matching) for the aria-hidden
31	  // check, and a separate manual parentElement walk for display/visibility,
32	  // since those need getComputedStyle rather than a selector match. Not
33	  // bounded by the measured root, and it does NOT consider transform/position,
34	  // so an element merely translated off-screen still fails.
35	  // The visually-hidden exemption is folded into the same predicate, but
36	  // expressed on the element's own rect rather than an ancestor walk: the
37	  // screen-reader-only pattern collapses the element itself, so the largest
38	  // side of its own box is what matters. Math.max(w, h) <= 1 is the same
39	  // boundary as "both dimensions at most 1px", just phrased the other way.
40	  // The 0x0 case is already gone by the time isExempt runs (the caller skips
41	  // zero-area rects first), so this only ever fires for a genuinely 1px box.
42	  const isExempt = (el, rect) => {
43	    if (el.closest('[aria-hidden="true"]')) return true;
44	    for (let e = el; e; e = e.parentElement) {
45	      const ecs = getComputedStyle(e);
46	      if (ecs.display === 'none' || ecs.visibility === 'hidden') return true;
47	    }
48	    return Math.max(rect.width, rect.height) <= 1;
49	  };
50	  if (document.documentElement.scrollWidth - vw > tol) {
51	    fails.push({ kind: 'viewport-escape', selector: 'html', detail: 'page scrolls horizontally' });
52	  }
53	  const root = document.querySelector(anchorSelector) || document.body;
54	  for (const el of root.querySelectorAll('*')) {
55	    const r = el.getBoundingClientRect();
56	    if (r.width <= 0 || r.height <= 0) continue;
57	    if (isExempt(el, r)) continue;
58	    const cs = getComputedStyle(el);
59	    if ((r.right - vw > tol || r.left < -tol) && !scrollAncestor(el, root)) {
60	      fails.push({ kind: 'element-escape', selector: sel(el), detail: 'right ' + Math.round(r.right) + ' vs ' + vw });
61	    }
62	    const hidX = (cs.overflowX === 'hidden' || cs.overflowX === 'clip') && el.scrollWidth - el.clientWidth > tol;
63	    const hidY = (cs.overflowY === 'hidden' || cs.overflowY === 'clip') && el.scrollHeight - el.clientHeight > tol;
64	    if (hidX || hidY) fails.push({ kind: 'element-clip', selector: sel(el), detail: 'clipped' });
65	  }
66	  return fails;
67	}
68	
69	export async function assertResponsive({ origin, route, breakpoints = [375, 768, 1280], tolerancePx = 1, anchorSelector = 'app-hero-detail', browser: given }) {
70	  const browser = given ?? (await launchChromium());
71	  const failures = [];
72	  try {
73	    for (const bp of breakpoints) {
74	      const { page, context } = await visitBreakpoint(browser, `${origin}/${route}`, bp);
75	      const fails = await page.evaluate(pageCheck, { tol: tolerancePx, anchorSelector });
76	      for (const f of fails) failures.push({ breakpoint: bp, ...f });
77	      await context.close();
78	    }
79	  } finally {
80	    if (!given) await browser.close();
81	  }
82	  return { failures };
83	}
84	
85	function parseCliArgs(argv) {
86	  const get = (f, d) => { const i = argv.indexOf(f); return i >= 0 ? argv[i + 1] : d; };
87	  return { anchor: get('--anchor', 'app-hero-detail') };
88	}
