// Scratch verification (outside the repo). Reuses the repo's responsive checker and
// static server, then drives one cross-screen flow in a real browser.
import { pathToFileURL } from 'node:url';
const ROOT = 'D:/Repos/angular-jig';
const { assertResponsive } = await import(pathToFileURL(`${ROOT}/harness/gate/check-responsive.mjs`).href);
const { serveStatic, launchChromium } = await import(pathToFileURL(`${ROOT}/harness/playwright/serve-and-visit.mjs`).href);

const DIST = `${ROOT}/dist/angular-jig/browser`;
const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
let failed = false;
try {
  for (const route of ['dashboard', 'roster', 'roster?q=sil', 'detail/11', 'missions', 'threats', 'recruit', 'settings']) {
    const { failures } = await assertResponsive({ origin: srv.origin, route, browser, anchorSelector: 'body' });
    console.log(route, failures.length ? 'FAIL' : 'ok', failures.slice(0, 4));
    if (failures.length) failed = true;
  }

  // Cross-screen flow: deploy from the detail screen, then check the dashboard tile moved.
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message)));
  await page.goto(`${srv.origin}/detail/1`, { waitUntil: 'networkidle' });
  await page.getByRole('button', { name: 'Deploy' }).click();
  await page.getByRole('link', { name: 'Dashboard' }).click();
  await page.waitForURL(/dashboard/);
  const tile = await page.locator('app-stat-tile', { hasText: 'Missions live' }).innerText();
  console.log('dashboard after deploy:', tile.replace(/\s+/g, ' '));
  await page.getByRole('link', { name: 'Missions' }).click();
  const live = await page.locator('article', { hasText: 'Rapid response: Silverwing' }).count();
  console.log('mission card visible on missions board:', live === 1);
  await page.getByRole('link', { name: 'Roster' }).click();
  await page.getByRole('searchbox', { name: 'Search heroes' }).fill('Ion');
  await page.getByRole('searchbox', { name: 'Search heroes' }).press('Enter');
  await page.waitForURL(/roster\?q=Ion/);
  const rows = await page.locator('tbody tr').count();
  console.log('roster rows for "Ion":', rows);
  console.log('page errors:', errors);
  if (errors.length) failed = true;
} finally {
  await browser.close();
  await srv.close();
}
process.exit(failed ? 1 : 0);

