// Scratch probe (outside the repo): measure the sidebar link clip and the search result.
import { pathToFileURL } from 'node:url';
const ROOT = 'D:/Repos/angular-jig';
const { serveStatic, launchChromium } = await import(pathToFileURL(`${ROOT}/harness/playwright/serve-and-visit.mjs`).href);
const srv = await serveStatic(`${ROOT}/dist/angular-jig/browser`, { spaFallback: true });
const browser = await launchChromium();
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(`${srv.origin}/dashboard`, { waitUntil: 'networkidle' });
  const probe = await page.evaluate(() =>
    [...document.querySelectorAll('a.ring-sidebar-ring')].slice(0, 2).map((el) => {
      const cs = getComputedStyle(el);
      const kids = [...el.children].map((c) => `${c.tagName}.${c.className.toString().slice(0, 60)} h=${c.getBoundingClientRect().height.toFixed(1)}`);
      return { sh: el.scrollHeight, ch: el.clientHeight, sw: el.scrollWidth, cw: el.clientWidth, ov: cs.overflow, h: cs.height, pad: cs.padding, lh: cs.lineHeight, kids, cls: el.className.toString().slice(0, 200) };
    }),
  );
  console.log(JSON.stringify(probe, null, 1));

  await page.goto(`${srv.origin}/roster`, { waitUntil: 'networkidle' });
  await page.getByRole('searchbox', { name: 'Search heroes' }).fill('Ion');
  await page.getByRole('searchbox', { name: 'Search heroes' }).press('Enter');
  await page.waitForURL(/roster\?q=Ion/);
